:root { color-scheme: dark; --ink:#f8fafc; --muted:#a8b6ca; --panel:#101621; --cyan:#39d9ff; --lime:#8cffb8; --gold:#ffd166; --rose:#ff6a8a; --violet:#b497ff; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; display:grid; place-items:center; font-family:Inter,Segoe UI,sans-serif; background:radial-gradient(circle at 48% 7%,#273b57,#070a12 70%); color:var(--ink); }
.pressure-shell { width:min(1120px,94vw); padding:32px 0; }
.pressure-panel { border:1px solid rgba(255,255,255,.12); border-radius:8px; padding:clamp(22px,4vw,44px); background:linear-gradient(145deg,rgba(16,22,33,.96),rgba(7,10,18,.98)); box-shadow:0 24px 80px rgba(0,0,0,.45); }
.eyebrow { margin:0 0 8px; color:var(--lime); text-transform:uppercase; font-size:13px; font-weight:800; letter-spacing:0; }
h1 { margin:0; font-size:clamp(36px,7vw,82px); letter-spacing:0; }
.summary { max-width:780px; color:var(--muted); line-height:1.65; }
.pressure-stage { position:relative; min-height:440px; margin-top:34px; overflow:hidden; border-radius:8px; background:repeating-linear-gradient(90deg,rgba(255,255,255,.04) 0 1px,transparent 1px 76px),linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.02)); }
.surge-lanes { position:absolute; left:36px; right:55%; top:58px; bottom:70px; display:grid; gap:32px; }.surge-lanes span{height:18px;border-radius:999px;background:linear-gradient(90deg,transparent,var(--cyan),var(--lime),transparent);box-shadow:0 0 24px rgba(57,217,255,.5);animation:surge 2.5s linear infinite}.surge-lanes span:nth-child(2){animation-delay:-.6s;opacity:.8}.surge-lanes span:nth-child(3){animation-delay:-1.2s;opacity:.65}.surge-lanes span:nth-child(4){animation-delay:-1.8s;opacity:.9}
.pressure-chamber { position:absolute; left:45%; top:50%; width:220px; height:270px; transform:translate(-50%,-50%); border:2px solid rgba(255,255,255,.18); border-radius:8px; display:grid; place-items:center; background:rgba(7,10,18,.76); }.pressure-chamber i{position:absolute;inset:26px;border:2px solid var(--gold);border-radius:50%;animation:pulse 2.4s ease-in-out infinite}.pressure-chamber i:nth-child(2){inset:58px;border-color:var(--rose);animation-delay:-1.2s}.pressure-chamber strong{color:var(--gold);text-transform:uppercase;font-size:17px}
.valve-core { position:absolute; right:15%; top:50%; width:220px; height:220px; transform:translateY(-50%); border-radius:50%; display:grid; place-items:center; background:radial-gradient(circle,rgba(140,255,184,.28),rgba(57,217,255,.1) 58%,transparent 60%); }.valve-core b{position:absolute;width:84%;height:12px;border-radius:999px;background:var(--lime);box-shadow:0 0 22px rgba(140,255,184,.55);animation:valve 3s ease-in-out infinite}.valve-core b:nth-child(2){transform:rotate(90deg);animation-delay:-1.5s}.valve-core em{font-style:normal;font-weight:900;color:var(--lime);text-transform:uppercase}
.cooldown-drain { position:absolute; left:52%; right:46px; bottom:45px; height:64px; border-top:2px solid rgba(255,106,138,.5); }.cooldown-drain small{color:var(--rose);text-transform:uppercase;font-weight:800}.cooldown-drain span{position:absolute;bottom:8px;width:18px;height:18px;border-radius:50%;background:var(--rose);animation:drain 3.4s ease-in-out infinite}.cooldown-drain span:nth-child(3){animation-delay:-1.1s}.cooldown-drain span:nth-child(4){animation-delay:-2.2s}
.readouts { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; margin-top:16px; }.readouts span{padding:12px 14px;border:1px solid rgba(255,255,255,.1);border-radius:8px;color:var(--muted);text-transform:uppercase;font-size:12px;font-weight:800}
@keyframes surge{from{transform:translateX(-20%);opacity:.3}50%{opacity:1}to{transform:translateX(80%);opacity:.16}}@keyframes pulse{0%,100%{transform:scale(.78);opacity:.45}50%{transform:scale(1.16);opacity:1}}@keyframes valve{0%,100%{width:84%;opacity:1}50%{width:36%;opacity:.72}}@keyframes drain{0%{left:4%;opacity:.2}50%{opacity:1}100%{left:84%;opacity:.2}}
@media(max-width:720px){.pressure-stage{min-height:570px}.surge-lanes{right:24px;left:24px;bottom:auto;height:190px}.pressure-chamber{left:50%;top:52%}.valve-core{right:auto;left:50%;top:78%;transform:translate(-50%,-50%);width:164px;height:164px}.cooldown-drain{left:24px;right:24px;bottom:24px}.readouts{grid-template-columns:1fr}}
